let data;
try { data = JSON.parse(localStorage.getItem(key)) || initialData(); } catch { data = initialData(); }
let ui={section:'overview',tab:'',query:'',filter:'all',period:'7',demo:'normal',chat:null,toolGroup:'all'};
let wizard={step:1,title:'',audience:'repeat',message:'',date:'',consent:false,id:null};
let toastTimer, dialogOpener, loadingTimer;
const persist = () => {try {localStorage.setItem(key, JSON.stringify(data));} catch {toast('تعذر الحفظ في المتصفح؛ ستبقى التغييرات لهذه الجلسة.');}};
function toast(text) {const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function status(text,kind=''){return `<span class="status ${kind}">${esc(text)}</span>`;}
const customer = id => data.contacts.find(c=>c.id===id) || data.contacts[0];
function avatar(c){return `<span class="avatar ${['sage','blue','rose'][c.id%3]}">${esc(c.name.charAt(0))}</span>`;}
function button(text,action,kind='',extras=''){return `<button class="button ${kind}" data-action="${action}" ${extras}>${text}</button>`;}
function route(s,t=''){return `#/${s}${t?'/'+t:''}`;}
function go(s,t=''){if(location.hash===route(s,t)){ui.demo='normal';render();}else location.hash=route(s,t);}
function navLinks(){return groups.slice(0,8).map(([id,title,i])=>`<a class="nav-link" href="${route(id)}" ${ui.section===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${id==='inbox'?`<span class="nav-count">${data.contacts.filter(c=>c.needs).length}</span>`:''}</a>`).join('')+`<div class="nav-secondary">${groups.slice(8).map(([id,title,i])=>`<a class="nav-link" href="${route(id)}" ${ui.section===id?'aria-current="page"':''}>${icon(i)}${title}</a>`).join('')}</div>`;}
const brand = `<a class="brand" href="#/overview"><span class="brand-mark">✦</span><div><div class="brand-name">ساري</div><small>شريك يومك</small></div></a>`;
function shell(){
  $('#sidebar').innerHTML=brand+`<div class="nav-label">مساحة العمل</div><nav aria-label="أقسام المتجر">${navLinks()}</nav><div class="sidebar-end"><a href="#/settings/billing" class="usage-mini" style="display:block"><div class="row between"><strong>باقة النمو</strong><span>هذا الشهر</span></div><div class="meter"><span style="width:38%"></span></div><div class="row between"><small>1,140 / 3,000 رسالة</small>${icon('left')}</div></a><div class="side-user">${avatar({name:'أحمد',id:1})}<div><strong>أحمد · مالك المتجر</strong><small>مساحة تجريبية</small></div></div>`;
  $('#topbar').innerHTML=`<div class="row"><button class="icon-button mobile-only" data-action="menu" aria-label="فتح القائمة">${icon('menu')}</button><a class="shop" href="#/settings"><span class="shop-symbol">ن</span><div><strong>${esc(data.shop)}</strong><small>قهوة مختصة، ولحظات أجمل</small></div></a></div><div class="header-actions"><span class="demo-pill">تصور تفاعلي · بيانات توضيحية</span><button class="search-button" data-action="search" aria-label="البحث في جميع الأدوات">${icon('search')}<span>ابحث عن أي شيء…</span><kbd>Ctrl K</kbd></button><button class="icon-button" data-action="notifications" aria-label="الإشعارات">${icon('bell')}</button></div>`;
  $('#bottom-nav').innerHTML=groups.slice(0,3).map(([id,title,i])=>`<a href="${route(id)}" ${ui.section===id?'aria-current="page"':''}>${icon(i)}${title}</a>`).join('')+`<button data-action="menu" ${!['overview','inbox','sales'].includes(ui.section)?'aria-current="page"':''}>${icon('grid')}المزيد</button>`;
}
function periodControl(){return `<label class="sr-only" for="period">فترة التقرير</label><select id="period" class="control" data-change="period"><option value="7" ${ui.period==='7'?'selected':''}>آخر 7 أيام</option><option value="30" ${ui.period==='30'?'selected':''}>آخر 30 يومًا</option></select>`;}
function heading(title,desc,actions='',eyebrow=''){return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function tabs(list){return `<nav class="tabs" aria-label="أقسام ${labels[ui.section]}">${list.map(([id,label])=>`<button class="tab" data-action="tab" data-id="${id}" aria-pressed="${ui.tab===id}">${label}</button>`).join('')}</nav>`;}
function searchField(placeholder='ابحث بالاسم…'){return `<div class="search-field">${icon('search')}<label class="sr-only" for="view-search">${placeholder}</label><input id="view-search" class="control" data-input="query" value="${esc(ui.query)}" placeholder="${placeholder}" autocomplete="off"></div>`;}
function kpi(label,value,note,i){return `<div class="panel kpi"><div class="kpi-top"><span>${label}</span>${icon(i)}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></div>`;}
function scopedOrders(){return data.orders.filter(o=>o.day>23-Number(ui.period));}
function revenue(){return scopedOrders().filter(o=>['paid','processing','shipped','delivered'].includes(o.status)).reduce((sum,o)=>sum+o.amount,0);}
function chart(){
  const days = ui.period==='7'?[17,18,19,20,21,22,23]:[0,4,8,12,16,20,23];
  const vals=days.map((day,i)=>scopedOrders().filter(o=>ui.period==='7'?o.day===day:o.day> (days[i-1]??-8)&&o.day<=day).filter(o=>o.status!=='pending').reduce((a,o)=>a+o.amount,0));
  const max=Math.ceil(Math.max(...vals,1)/500)*500;
  return `<div class="chart-wrap" role="img" aria-label="الإيراد المحصل خلال ${ui.period} يومًا: ${money(revenue())} ريال. بيانات توضيحية."><div class="y-axis"><span>${money(max)}</span><span>${money(max*.75)}</span><span>${money(max*.5)}</span><span>${money(max*.25)}</span><span>0</span></div><div class="bars">${days.map((d,i)=>`<div class="bar-col" title="${d?d+' سبتمبر':'25–31 أغسطس'}: ${money(vals[i])} ر.س"><span class="bar-fill" style="height:${Math.max(1,vals[i]/max*100)}%"></span><small>${ui.period==='7'?d+' سبتمبر':i===0?'25 أغسطس':d+' سبتمبر'}</small></div>`).join('')}</div></div>`;
}
const orderStatus={pending:['بانتظار الدفع','amber'],paid:['مدفوع','blue'],processing:['قيد التجهيز','amber'],shipped:['تم الشحن','blue'],delivered:['تم التسليم','']};
function orderTable(orders,compact=false){return `<div class="table-scroll responsive-table"><table><thead><tr><th>الطلب</th><th>العميل</th><th>المبلغ</th><th>الحالة</th><th class="hide-mobile">التاريخ</th><th>التفاصيل</th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong dir="ltr">#${o.id}</strong><small>${o.items===1?'منتج واحد':o.items===2?'منتجان':o.items+' منتجات'}</small></td><td>${esc(customer(o.customer).name)}</td><td><strong>${money(o.amount)}</strong> <small style="display:inline">ر.س</small></td><td>${status(...orderStatus[o.status])}</td><td class="hide-mobile">${o.day} سبتمبر 2026</td><td><button class="table-row-button" data-action="order" data-id="${o.id}" aria-label="عرض الطلب ${o.id}">${compact?icon('left'):'عرض الطلب'}</button></td></tr>`).join('')}</tbody></table></div>`;}
function overview(){return heading('صباح الخير، أحمد','هذه أبرز مستجدات متجرك. لنبدأ بما يحتاج انتباهك.',periodControl()+button(icon('plus')+'إجراء سريع','quick','primary'),'الأربعاء، 23 سبتمبر 2026')+
  `<section class="panel attention" aria-label="مهام تحتاج انتباهك"><div class="attention-title"><span class="orb">${icon('spark')}</span><div><h2>خطوتك التالية</h2><p>أشياء صغيرة تصنع فرقًا اليوم</p></div></div><div class="attention-items"><button class="attention-item" data-action="needs"><span><b>${data.contacts.filter(c=>c.needs).length} محادثات</b><small>تحتاج ردك</small></span>${icon('left')}</button><a class="attention-item" href="#/catalog"><span><b>${data.products.filter(p=>p.stock===0).length} منتج نفد</b><small>راجع المخزون</small></span>${icon('left')}</a><a class="attention-item" href="#/marketing"><span><b>${data.campaigns.filter(c=>c.status==='draft').length} حملة مسودة</b><small>أكمل تجهيزها</small></span>${icon('left')}</a></div></section>`+
  `<section class="kpis" aria-label="ملخص الأداء">${kpi('الإيراد المحصّل',money(revenue())+' <small>ر.س</small>','للطلبات المدفوعة خلال الفترة','wallet')}${kpi('إجمالي الطلبات',scopedOrders().length,'تشمل الطلبات بانتظار الدفع','bag')}${kpi('محادثات العملاء',data.contacts.length,'إجمالي السجل التجريبي','chat')}${kpi('طلبات تم تسليمها',scopedOrders().filter(o=>o.status==='delivered').length,'بناءً على حالة «تم التسليم»','check')}</section>`+
  `<div class="overview-grid"><section class="panel panel-pad"><div class="panel-head"><div><h2>مبيعاتك خلال الفترة</h2><p>توزيع الإيراد المحصّل بالريال السعودي</p></div><span class="chart-legend"><i></i>الإيراد</span></div>${chart()}<div class="chart-foot"><span>لا تشمل الطلبات غير المدفوعة</span><a href="#/analytics" class="text-link">استكشف التحليلات ${icon('left')}</a></div></section><section class="panel panel-pad assistant-panel"><div class="panel-head"><h2>ساري، إلى جانبك</h2>${status('محاكاة')}</div><div class="assistant-stat">${data.contacts.filter(c=>!c.needs).length} <span>محادثة</span></div><h3>لا تنتظر تدخلًا منك</h3><div class="meter"><span style="width:${data.contacts.filter(c=>!c.needs).length/65*100}%"></span></div><div class="row between"><small>من ${data.contacts.length} محادثة توضيحية</small><small>${data.contacts.filter(c=>c.needs).length} تحتاجك</small></div><a href="#/ai/test" class="button">${icon('spark')} جرّب تجربة العميل ${icon('left')}</a></section></div>`+
  `<section class="panel"><div class="panel-head table-top"><div><h2>آخر الطلبات</h2><p>تابع الرحلة من أول طلب إلى التسليم</p></div><a class="text-link" href="#/sales">كل الطلبات ${icon('left')}</a></div>${orderTable(data.orders.slice(0,4),true)}</section>`;}
function inbox(){
  const list=data.contacts.filter(c=>(ui.filter!=='needs'||c.needs)&&(c.name+' '+c.ref+' '+c.messages.map(m=>m.text).join(' ')).includes(ui.query));
  const c=data.contacts.find(c=>c.id===ui.chat);
  return heading('المحادثات','كل العملاء في مكان واحد. ابحث في كامل السجل، وتابع الحديث بسياقه.',`<span class="status gray">${data.contacts.length} محادثة في السجل</span>`)+
  `<section class="panel inbox ${c?'chat-selected':''}"><div class="conversation-list"><div class="conversation-search">${searchField('ابحث بالاسم أو مرجع العميل')}<div class="row between"><label for="inbox-filter">عرض</label><select id="inbox-filter" class="control" data-change="filter"><option value="all">كل المحادثات</option><option value="needs" ${ui.filter==='needs'?'selected':''}>تحتاج ردًا</option></select><span>${list.length} نتيجة</span></div></div><div class="conversation-items">${list.length?list.map(x=>`<button class="conversation-item ${x.id===ui.chat?'selected':''}" data-action="chat" data-id="${x.id}" ${x.id===ui.chat?'aria-current="true"':''}>${avatar(x)}<div class="conversation-snippet"><strong>${esc(x.name)}</strong><p>${esc(x.messages.at(-1).text)}</p></div><span class="conversation-time">${esc(x.messages.at(-1).time)}${x.needs?'<span class="unread">1</span>':''}</span></button>`).join(''):'<div class="no-results">لا توجد نتائج لهذا البحث.<br>جرّب اسمًا أو مرجعًا آخر.</div>'}</div><div class="table-bottom">البحث يشمل جميع المحادثات الـ${data.contacts.length}</div></div><div class="chat">${c?chatView(c):`<div class="empty-chat">${icon('chat')}<h2>اختر محادثة للبدء</h2><p>سياق العميل وإجراءاتك، بجانب الحديث.</p></div>`}</div></section>`;
}
function chatView(c){return `<div class="chat-head"><button class="icon-button mobile-only chat-back" data-action="chat-back" aria-label="العودة لقائمة المحادثات">${icon('right')}</button>${avatar(c)}<div><h2>${esc(c.name)}</h2><small>${c.needs?'تحتاج ردًا منك':'تمت المتابعة'} · محادثة توضيحية</small></div><button class="button small spacer" data-action="customer" data-id="${c.id}">ملف العميل</button></div><div class="chat-body"><div class="chat-date">اليوم · 23 سبتمبر</div>${c.messages.map(m=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}<small>${m.me?'أنت · ':''}${esc(m.time)}</small></div>`).join('')}<div class="chat-note">أنت تدير هذه المحادثة الآن</div></div><form class="composer" data-form="message"><div class="row"><div class="field"><label class="sr-only" for="message">رسالتك للعميل</label><input id="message" name="message" required maxlength="1500" placeholder="اكتب ردك هنا…" autocomplete="off"></div><button class="button primary" type="submit" aria-label="إضافة الرد للمحادثة">${icon('send')} رد</button></div><small>تجربة محلية؛ الرسالة تضاف إلى النموذج فقط.</small></form>`;}
function sales(){
  const list=scopedOrders().filter(o=>(ui.filter==='all'||o.status===ui.filter)&&(`${o.id} ${customer(o.customer).name}`).includes(ui.query));
  const tab=ui.tab;
  let content='';
  if(tab==='orders')content=`<div class="toolbar">${searchField('ابحث برقم الطلب أو اسم العميل')}<div class="row"><label class="sr-only" for="order-filter">حالة الطلب</label><select id="order-filter" class="control" data-change="filter"><option value="all">كل الحالات</option>${Object.entries(orderStatus).map(([k,v])=>`<option value="${k}" ${ui.filter===k?'selected':''}>${v[0]}</option>`).join('')}</select>${periodControl()}</div></div><section class="panel">${list.length?orderTable(list):'<div class="no-results">لا توجد طلبات تطابق البحث أو الحالة.</div>'}<div class="table-bottom"><span>عرض ${list.length} من ${scopedOrders().length} طلبًا</span><span>جميع الأوقات بتوقيت الرياض</span></div></section>`;
  if(tab==='quotes'||tab==='links'){
    const arr=tab==='quotes'?data.quotes:data.paymentLinks;
    content=`<div class="callout">${icon('file')}<div><strong>${tab==='quotes'?'عرض واضح، قبل قرار الشراء':'رابط مستقل لكل دفعة'}</strong><p>إنشاء ومعاينة محلية. لا يتم إرسال عرض أو تحصيل أي مبلغ من هذا النموذج.</p></div></div><div class="panel panel-pad">${arr.length?arr.map(x=>`<div class="list-row"><span class="icon-tile">${icon(tab==='quotes'?'file':'link')}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.customer)} · ${money(x.amount)} ر.س</p></div>${status('مسودة','gray')}</div>`).join(''):empty('لا توجد مسودات بعد','ابدأ بمسودة تتضمن العميل والمبلغ والغرض، ثم راجعها قبل مشاركتها.',button('إنشاء '+(tab==='quotes'?'عرض سعر':'رابط تجريبي'),tab==='quotes'?'new-quote':'new-link','primary'),'file')}</div>`;
  }
  return heading('المبيعات','طلباتك وعروضك ومدفوعات عملائك، في مسار واحد.',button(icon('plus')+(tab==='links'?'إنشاء رابط':tab==='quotes'?'عرض سعر جديد':'عرض سعر جديد'),tab==='links'?'new-link':'new-quote','primary'))+tabs([['orders','الطلبات'],['quotes','عروض الأسعار'],['links','روابط الدفع']])+content;
}
function catalog(){
  const type=ui.tab==='services'?'service':'product';
  const list=data.products.filter(p=>p.type===type&&p.name.includes(ui.query)&&(ui.filter==='all'||(ui.filter==='available'?p.stock>0:p.stock===0)));
  return heading('الكتالوج','قدّم منتجاتك وخدماتك بوضوح، واحتفظ بمصدر واحد للمعلومة.',button(icon('plus')+(type==='service'?'إضافة خدمة':'إضافة منتج'),'new-product','primary',`data-type="${type}"`))+tabs([['products','المنتجات'],['services','الخدمات'],['bookings','الحجوزات']])+
  (ui.tab==='bookings'?`<div class="panel panel-pad"><div class="panel-head"><h2>الأربعاء، 23 سبتمبر</h2>${status('توقيت الرياض','gray')}</div>${[['11:00','جلسة تذوق القهوة','نورة السالم'],['16:00','ورشة التحضير المنزلي','عبدالله الحربي']].map((b,i)=>`<div class="list-row"><span class="icon-tile">${icon('calendar')}</span><div><h3>${b[1]}</h3><p>${b[2]} · ${b[0]} · ${i?'120':'60'} دقيقة</p></div><button class="button small spacer" data-action="booking" data-id="${i}">عرض الحجز</button></div>`).join('')}</div>`:
  `<div class="toolbar">${searchField(type==='product'?'ابحث عن منتج…':'ابحث عن خدمة…')}<label class="sr-only" for="stock-filter">توفر المخزون</label><select id="stock-filter" class="control" data-change="filter"><option value="all">كل حالات التوفر</option><option value="available" ${ui.filter==='available'?'selected':''}>متوفر</option><option value="out" ${ui.filter==='out'?'selected':''}>غير متوفر</option></select></div><div class="catalog-grid">${list.length?list.map(p=>`<article class="panel product"><div class="product-art ${p.tone}">${icon(p.art)}<span class="sku">NAWA / ${String(p.id).padStart(3,'0')}</span></div><div class="product-info"><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="product-meta"><div><b>${money(p.price)}</b> <small>ر.س</small></div>${status(p.stock>0?`${p.stock} ${p.type==='service'?'مقاعد':'بالمخزون'}`:'نفد المخزون',p.stock?'':'amber')}</div><div class="row between"><span class="source-tag">${icon('link')}المصدر: ${esc(p.source)}</span><button class="text-link" data-action="product" data-id="${p.id}">التفاصيل ${icon('left')}</button></div></div></article>`).join(''):'<div class="no-results">لا توجد نتائج مطابقة.</div>'}</div>`);
}
function customers(){
  const list=data.contacts.filter(c=>(c.name+' '+c.ref).includes(ui.query));
  return heading('العملاء','صورة واحدة لكل عميل: محادثاته، طلباته، وملاحظاتك.',button(icon('download')+'تصدير العملاء','export-customers'))+`<div class="toolbar">${searchField('ابحث بالاسم أو مرجع العميل')}<span class="hint">${list.length} عميلًا</span></div><section class="panel"><div class="table-scroll responsive-table"><table><thead><tr><th>العميل</th><th>الطلبات</th><th>قيمة الطلبات</th><th>المتابعة</th><th>الملف</th></tr></thead><tbody>${list.map(c=>{const orders=data.orders.filter(o=>o.customer===c.id);return `<tr><td><div class="row">${avatar(c)}<div><strong>${esc(c.name)}</strong><small dir="ltr">${c.ref}</small></div></div></td><td>${orders.length} طلبات</td><td>${money(orders.reduce((a,o)=>a+o.amount,0))} ر.س</td><td>${status(c.needs?'تحتاج متابعة':'مكتملة',c.needs?'amber':'gray')}</td><td><button class="table-row-button" data-action="customer" data-id="${c.id}">عرض الملف</button></td></tr>`;}).join('')||'<tr><td colspan="5">لا توجد نتائج مطابقة.</td></tr>'}</tbody></table></div></section>`;
}
function ai(){
  let content='';
  if(ui.tab==='knowledge')content=`<div class="setting-layout"><section class="panel panel-pad"><div class="panel-head"><div><h2>مصادر معرفة ساري</h2><p>راجع المعلومة من مصدرها، ثم جرّب الإجابة.</p></div>${status('بيانات محاكاة','gray')}</div>${[['box','الكتالوج',`${data.products.length} منتجات وخدمات · مصدر منظم`],['file','سياسة الشحن والاسترجاع','مستند واحد · آخر مراجعة اليوم'],['chat','أسئلة العملاء الشائعة','12 سؤالًا · تمت مراجعتها']].map((v,i)=>`<div class="list-row"><span class="icon-tile">${icon(v[0])}</span><div><h3>${v[1]}</h3><p>${v[2]}</p></div><button class="button small spacer" data-action="knowledge" data-id="${i}">مراجعة</button></div>`).join('')}</section><aside class="panel panel-pad"><div class="eyebrow">قبل أن تفعّل المساعد</div><h2>إجابة صحيحة تبدأ<br>بمعلومة واضحة</h2><p class="hint" style="margin:16px 0 24px">اجمع المعرفة، راجع السياسات، واختبر أسئلة حقيقية من عملائك. يعرض النموذج إجابات محلية ثابتة لتجربة الواجهة.</p><a class="button primary" href="#/ai/test">${icon('spark')}جرّب المساعد</a></aside></div>`;
  if(ui.tab==='behavior')content=`<div class="setting-layout"><form class="panel panel-pad form-stack" data-form="ai"><h2>الأسلوب وحدود التدخل</h2><div class="field"><label for="tone">أسلوب الرد</label><select id="tone" name="tone"><option value="warm" ${data.ai.tone==='warm'?'selected':''}>ودود وواضح</option><option value="formal" ${data.ai.tone==='formal'?'selected':''}>رسمي ومختصر</option></select></div><div class="field"><label for="hours">ساعات توفر فريقك</label><input id="hours" name="hours" value="${esc(data.ai.hours)}" required maxlength="80"><small>بتوقيت الرياض. يوضّح المساعد وقت الرد خارج الدوام.</small></div><label class="check-label"><input name="handoff" type="checkbox" ${data.ai.handoff?'checked':''}><span>تحويل المحادثة إلى الفريق عند طلب العميل أو عدم توفر إجابة موثوقة.</span></label><div class="setting-footer"><button class="button primary" type="submit">حفظ التفضيلات</button><span class="save-indicator" id="save-indicator">محفوظة في هذا المتصفح</span></div></form><aside class="info-box"><h3>يبقى القرار بيدك</h3><p>التعليمات تحدد طريقة الحديث. الأسعار والمخزون تأتي من الكتالوج، وحالة الطلب تأتي من سجل الطلبات.</p></aside></div>`;
  if(ui.tab==='test')content=`<div class="setting-layout"><section class="panel panel-pad"><div class="panel-head"><div><h2>تجربة من منظور عميلك</h2><p>محاكاة محلية للإجابة ومصدرها.</p></div>${status('تجربة','gray')}</div><div class="summary-box" id="ai-response"><p>جرّب: «كم سعر بن كولومبيا؟» أو «ما مدة الشحن؟»</p></div><form class="form-stack" data-form="ai-test" style="margin-top:20px"><div class="field"><label for="ai-question">سؤال العميل</label><input id="ai-question" name="question" required maxlength="500" placeholder="اكتب سؤالًا عن متجرك…"></div><button class="button primary" type="submit">${icon('spark')} اختبر الإجابة</button></form></section><aside class="panel panel-pad"><h2>ما الذي تراجعه؟</h2><div class="list-row"><span class="icon-tile">${icon('check')}</span><div><h3>المعلومة دقيقة</h3><p>السعر والسياسة مطابقان للمصدر.</p></div></div><div class="list-row"><span class="icon-tile">${icon('chat')}</span><div><h3>الأسلوب يمثلك</h3><p>رد واضح، قصير، ومفيد.</p></div></div><div class="list-row"><span class="icon-tile">${icon('users')}</span><div><h3>يعرف متى يحوّل</h3><p>إذا لم يعرف، يطلب مساعدة الفريق.</p></div></div></aside></div>`;
  if(ui.tab==='operation')content=`<section class="panel panel-pad"><div class="panel-head"><h2>حالة التشغيل</h2>${status('غير متصل','amber')}</div><div class="callout">${icon('link')}<div><strong>اربط قناة لتبدأ استقبال العملاء</strong><p>حفظ إعدادات المساعد لا يعني أنه يعمل على واتساب. يظهر الاتصال والتشغيل كحالتين منفصلتين.</p></div></div><div class="list-row"><div><h3>المعرفة</h3><p>مصادر محلية جاهزة للتجربة</p></div>${status('تمت المراجعة')}</div><div class="list-row"><div><h3>قناة واتساب</h3><p>لا يوجد اتصال فعلي في الموك أب</p></div>${status('لم تُربط','amber')}</div><div class="list-row"><div><h3>الرد التلقائي</h3><p>يصبح متاحًا بعد الربط والتجربة</p></div>${status('متوقف','gray')}</div><a class="button primary" href="#/settings/integrations" style="margin-top:20px">إعداد القنوات ${icon('left')}</a></section>`;
  return heading('المساعد الذكي','معرفة موثوقة، أسلوب يمثلك، وتحكم واضح في التشغيل.')+tabs([['knowledge','المعرفة'],['behavior','السلوك والدوام'],['test','التجربة'],['operation','التشغيل']])+content;
}
function marketing(){return heading('التسويق','جهّز حملتك خطوة بخطوة، وراجع كل شيء قبل الجدولة.',button(icon('plus')+'إنشاء حملة','campaign-new','primary'))+
  `<div class="callout">${icon('shield')}<div><strong>رسائل ينتظرها عملاؤك</strong><p>اختر جمهورًا وافق على الرسائل، واكتب عرضًا واضحًا مع إمكانية إلغاء الاشتراك.</p></div></div><div class="campaign-grid">${data.campaigns.map(c=>`<article class="panel campaign-card"><div class="row between">${status(c.status==='draft'?'مسودة':'مجدولة',c.status==='draft'?'gray':'blue')}${icon('megaphone')}</div><h2>${esc(c.title)}</h2><p>${esc(c.message)}</p><div class="campaign-numbers"><div><strong>${c.audience==='all'?'65':'8'}</strong><small>مستلمًا توضيحيًا</small></div><div><strong>${c.status==='draft'?'—':esc(c.date?.slice(11,16)||'—')}</strong><small>${c.status==='draft'?'لم تُجدول':esc(c.date?.slice(0,10)||'موعد تجريبي')}</small></div></div>${button(c.status==='draft'?'أكمل المسودة':'مراجعة الجدولة','campaign-edit','',`data-id="${c.id}"`)}</article>`).join('')}</div><div class="panel panel-pad" style="margin-top:22px"><div class="panel-head"><div><h2>أدوات تنمية العلاقة</h2><p>مسارات فرعية ضمن التسويق، يسهل الوصول إليها عند الحاجة.</p></div><a class="text-link" href="#/tools/marketing">جميع أدوات التسويق ${icon('left')}</a></div><div class="segmented">${['كوبونات الخصم','السلات المتروكة','حملات المناسبات','إعدادات الولاء'].map(t=>`<button data-action="feature-title" data-title="${t}">${t}</button>`).join('')}</div></div>`;}
function analytics(){return heading('التحليلات','أرقام بتعريفات واضحة وفترة واحدة في كل التقرير.',periodControl()+button(icon('download')+'تصدير CSV','export-orders'))+
  `<div class="kpis">${kpi('الإيراد المحصّل',money(revenue())+' <small>ر.س</small>','يستبعد الطلبات غير المدفوعة','wallet')}${kpi('إجمالي الطلبات',scopedOrders().length,'حسب تاريخ إنشاء الطلب','bag')}${kpi('متوسط الطلب المدفوع',money(revenue()/Math.max(1,scopedOrders().filter(o=>o.status!=='pending').length))+' <small>ر.س</small>','الإيراد ÷ عدد الطلبات المدفوعة','chart')}${kpi('طلبات تم تسليمها',scopedOrders().filter(o=>o.status==='delivered').length,'الحالة الحالية للطلب','check')}</div><div class="overview-grid"><section class="panel panel-pad"><div class="panel-head"><h2>الإيراد خلال ${ui.period} يومًا</h2>${status('بيانات توضيحية','gray')}</div>${chart()}<div class="chart-foot"><span>العملة: ريال سعودي</span><span>الفترة تنتهي في 23 سبتمبر 2026</span></div></section><section class="panel panel-pad"><h2>توزيع حالات الطلبات</h2>${Object.entries(orderStatus).map(([s,t])=>`<div class="list-row"><span>${t[0]}</span><strong class="spacer">${scopedOrders().filter(o=>o.status===s).length}</strong></div>`).join('')}</section></div><section class="panel panel-pad"><div class="panel-head"><div><h2>كيف نقرأ هذه الأرقام؟</h2><p>تعريف المؤشر جزء من التقرير.</p></div>${icon('file')}</div><p class="hint">الإيراد المحصّل هنا يمثل مجموع الطلبات المدفوعة أو قيد التجهيز أو المشحونة أو المسلّمة. الطلب المسلّم يُحتسب من حالة «تم التسليم». في التنفيذ الفعلي يجب اشتقاق صافي الإيراد من المعاملات المؤكدة بعد الاستردادات، مع توثيق توقيت القياس. لا توجد مقارنة نمو أو تقييم رضا حين لا تتوفر عينة موثوقة.</p></section>`;}
function settings(){
  let content='';
  if(ui.tab==='store')content=`<div class="setting-layout"><form class="panel panel-pad form-stack" data-form="store"><h2>هوية المتجر</h2><div class="field"><label for="shop-name">اسم المتجر</label><input id="shop-name" name="name" required maxlength="40" value="${esc(data.shop)}"></div><div class="field-grid"><div class="field"><label for="currency">عملة العرض</label><select id="currency"><option>الريال السعودي (SAR)</option></select></div><div class="field"><label for="timezone">المنطقة الزمنية</label><select id="timezone"><option>الرياض (UTC+3)</option></select></div></div><label class="check-label"><input type="checkbox" name="notifications" ${data.notifications?'checked':''}><span>إظهار إشعارات المهام التي تحتاج تدخلي.</span></label><div class="setting-footer"><button class="button primary" type="submit">حفظ التغييرات</button><small>يحفظ في هذا المتصفح</small></div></form><aside class="panel panel-pad"><h2>خصوصية الحساب</h2><p class="hint" style="margin:14px 0">بيانات المتجر وصلاحيات الفريق في مكان واضح، مع شرح أثر كل تغيير قبل اعتماده.</p><button class="text-link" data-action="feature-title" data-title="الخصوصية">مقترح مركز الخصوصية ${icon('left')}</button></aside></div>`;
  if(ui.tab==='integrations')content=`<div class="callout">${icon('link')}<div><strong>حالة موثوقة لكل اتصال</strong><p>هذه معاينة لمسار الربط. لا يطلب النموذج مفاتيح فعلية ولا يتصل بأي مزود خارجي.</p></div></div><div class="integration-grid">${[['واتساب','و','استقبل محادثات العملاء من رقم متجرك.'],['سلة','س','منتجات وطلبات ومخزون من مصدر واحد.'],['زد','ز','أدر بيانات متجرك ضمن الكتالوج والمبيعات.'],['WooCommerce','W','زامن كتالوج متجرك وطلبات عملائك.'],['Google Calendar','G','نظّم مواعيد الخدمات وتوفر فريقك.'],['Google Sheets','G','صدّر البيانات واربط التقارير.']].map((v,i)=>`<article class="panel integration-card"><div class="row between"><span class="integration-symbol">${v[1]}</span>${status('غير مرتبط','gray')}</div><h2>${v[0]}</h2><p>${v[2]}</p>${button('معاينة خطوات الربط','integration','',`data-id="${i}"`)}</article>`).join('')}</div>`;
  if(ui.tab==='team')content=`<section class="panel panel-pad"><div class="panel-head"><h2>أعضاء الفريق</h2>${status('المالك + عضو توضيحي','gray')}</div><div class="list-row">${avatar({id:1,name:'أحمد'})}<div><h3>أحمد · أنت</h3><p>مالك المتجر · جميع الصلاحيات</p></div>${status('مالك')}</div><div class="list-row">${avatar({id:2,name:'سارة'})}<div><h3>سارة</h3><p>خدمة العملاء · المحادثات وملفات العملاء</p></div><button class="button small spacer" data-action="permissions">معاينة الصلاحيات</button></div><p class="hint" style="margin-top:20px">هذا تصور لأدوار الفريق. إرسال الدعوات وتعديل الصلاحيات الفعلية يتطلبان ربط الخادم والتحقق من دور المستخدم.</p></section>`;
  if(ui.tab==='billing')content=`<div class="setting-layout"><section class="panel panel-pad"><div class="row between"><h2>باقة النمو</h2>${status('مثال توضيحي','gray')}</div><div class="plan-price">199 <small>ر.س / شهريًا</small></div><p class="hint">قيمة افتراضية لمعاينة العرض وليست تسعيرًا معتمدًا.</p><div class="list-row"><div><h3>رسائل هذه الدورة</h3><p>من 1 إلى 30 سبتمبر</p></div><strong class="spacer">1,140 / 3,000</strong></div><div class="meter"><span style="width:38%"></span></div><div class="list-row"><div><h3>حد العملاء</h3><p>65 عميلًا في السجل المحلي</p></div><strong class="spacer">65 / 1,000</strong></div></section><aside class="info-box"><h3>اشتراك ساري ومدفوعات العملاء</h3><p>تُعرض فواتير المنصة هنا. معاملات مشتريات عملائك وروابط الدفع تجدها في المبيعات، حتى يبقى سياق كل مبلغ واضحًا.</p><a href="#/sales/links" class="text-link">روابط دفع العملاء ${icon('left')}</a></aside></div>`;
  return heading('الإعدادات','حسابك وقنواتك وفريقك، دون تكرار أو تعقيد.')+tabs([['store','المتجر'],['integrations','التكاملات'],['team','الفريق والصلاحيات'],['billing','الباقة والاستخدام']])+content;
}
function toolsPage(){
  const group=ui.tab||'all';
  const list=window.FEATURES.map((f,i)=>({...f,index:i})).filter(f=>(group==='all'||f.group===group)&&(f.title+' '+f.routes.join(' ')).toLowerCase().includes(ui.query.toLowerCase()));
  return heading('جميع الأدوات','102 واجهة حالية، موزعة على أقسام واضحة. اختر أداة لمراجعة موضعها ومقترح تحسينها.',`<a class="button" href="report.html">${icon('file')}تقرير الفحص</a>`)+`<div class="toolbar">${searchField('ابحث باسم أداة أو مسار…')}<label class="sr-only" for="tools-filter">قسم الأداة</label><select id="tools-filter" class="control" data-change="tool-group"><option value="all">كل الأقسام</option>${groups.slice(0,9).map(g=>`<option value="${g[0]}" ${group===g[0]?'selected':''}>${g[1]}</option>`).join('')}</select></div><div class="tool-count">${list.length} أداة · خريطة تنظيم، مع معاينة تفاصيل المقترح</div><div class="tool-grid">${list.map(f=>`<button class="tool-card" data-action="feature" data-id="${f.index}">${icon(groups.find(g=>g[0]===f.group)?.[2])}<span><strong>${esc(f.title)}</strong><small>${labels[f.group]} · ${f.routes.length} ${f.routes.length>1?'مسارات':'مسار'}</small></span></button>`).join('')||'<p>لا توجد أداة تطابق بحثك.</p>'}</div>`;
}
function empty(title,desc,action='',i='box'){return `<div class="empty">${icon(i)}<h2>${title}</h2><p>${desc}</p>${action}</div>`;}
function demoState(){
  const title=labels[ui.section];
  const head=heading(title,ui.demo==='error'?'تعذر الحصول على بيانات هذه الصفحة.':'حالة توضيحية لاختبار تجربة الصفحة.');
  if(ui.demo==='empty')return head+`<section class="panel">${empty('مساحتك جاهزة للبداية','لا توجد بيانات بعد. سيظهر نشاط متجرك هنا عندما تبدأ استخدام هذا القسم.',button('العودة للبيانات التوضيحية','retry','primary'))}</section>`;
  if(ui.demo==='error')return head+`<section class="panel">${empty('تعذر تحميل البيانات','لم نتمكن من تحديث البيانات. تحقق من الاتصال ثم أعد المحاولة؛ لم تتغير بياناتك.',button(icon('refresh')+'إعادة المحاولة','retry','primary'),'alert')}</section>`;
  return head+`<section class="panel panel-pad" aria-busy="true" aria-label="جاري تحميل البيانات"><p role="status">جاري تحميل البيانات…</p><div class="skeleton skeleton-title" style="margin-top:25px"></div>${[1,2,3,4].map(()=>'<div class="skeleton skeleton-row"></div>').join('')}</section>`;
}
const renderers={overview,inbox,sales,catalog,customers,ai,marketing,analytics,settings,tools:toolsPage};
function render(keepFocus=false){
  const focus=keepFocus?document.activeElement:null,id=focus?.id,start=focus?.selectionStart,end=focus?.selectionEnd;
  shell(); $('#main').innerHTML=ui.demo==='normal'?renderers[ui.section]():demoState();
  document.title=`${labels[ui.section]} · ساري`;
  if(id){const el=document.getElementById(id);el?.focus({preventScroll:true});if(typeof start==='number'&&el?.setSelectionRange)el.setSelectionRange(start,end);}
  if(ui.section==='inbox'&&ui.chat){const body=$('.chat-body');if(body)body.scrollTop=body.scrollHeight;}
}
function onRoute(){
  const [section='overview',tab='']=location.hash.replace(/^#\/?/,'').split('/');
  ui.section=renderers[section]?section:'overview';
  const allowed={sales:['orders','quotes','links'],catalog:['products','services','bookings'],ai:['knowledge','behavior','test','operation'],settings:['store','integrations','team','billing'],tools:['all',...groups.slice(0,9).map(g=>g[0])]};
  ui.tab=allowed[ui.section]?.includes(tab)?tab:(allowed[ui.section]?.[0]||'');
  ui.query='';ui.filter='all';ui.demo='normal';ui.chat=null;
  if($('#dialog').open)$('#dialog').close();if($('#nav-dialog').open)$('#nav-dialog').close();
  clearTimeout(loadingTimer);render();window.scrollTo(0,0);
  if(document.activeElement!==document.body)$('#main').focus({preventScroll:true});
}
function openDialog(title,body){
  const d=$('#dialog');if(!d.open)dialogOpener=document.activeElement;
  d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="إغلاق النافذة">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;
  if(!d.open)d.showModal();
  const input=d.querySelector('[autofocus]');if(input)input.focus();
}
